mapper.select:
SELECT LOG_ID, INST_CD, TX_TYPE, TRACE_NO, REQ_DT, ELAPSED_MS, RESULT_CD, RESPONSE_CD, REQ_BYTES, RES_BYTES, REQ_HASH, ERROR_MSG
  FROM TB_FEP_MSG_LOG

    AND INST_CD = #{c.instCd}
    AND TRACE_NO = #{c.traceNo}
    AND RESULT_CD = #{c.resultCd}
    AND REQ_DT >= #{c.reqFrom} AND REQ_DT < #{c.reqTo}

 ORDER BY LOG_ID DESC
 LIMIT #{c.limit}
